SELECT DISTINCT c.code
FROM country c
WHERE c.language_code IS NULL;

SELECT COUNT(DISTINCT p.hand) as hand_count
FROM players p
GROUP BY p.hand;

SELECT p.first_name, p.birth_date
FROM players p
WHERE p.country_code = 'USA';

SELECT COUNT(DISTINCT d.department_id) AS department_count
FROM departments d
JOIN degree_programs dp ON d.department_id = dp.department_id;
